class Solution {
    public int findMinDifference(List<String> timePoints) {
        if (timePoints.size() > 1440) return 0;
        int[] minutes = new int[timePoints.size()];
        for (int i = 0; i < timePoints.size(); i++) {
            String t = timePoints.get(i);
            int h = Integer.parseInt(t.substring(0, 2));
            int m = Integer.parseInt(t.substring(3, 2));
            minutes[i] = h * 60 + m;
        }
        Arrays.sort(minutes);
        int minDiff = 1440 + minutes[0] - minutes[minutes.length - 1];
        for (int i = 1; i < minutes.length; i++) {
            minDiff = Math.min(minDiff, minutes[i] - minutes[i - 1]);
        }
        return minDiff;
    }
}

var findMinDifference = function(timePoints) {
    if (timePoints.length > 1440) return 0;
    const minutes = [];
    for (const t of timePoints) {
        const h = Number(t.slice(0, 2));
        const m = Number(t.slice(3, 5));
        minutes.push(h * 60 + m);
    }
    minutes.sort((a, b) => a - b);
    let minDiff = 1440 + minutes[0] - minutes[minutes.length - 1];
    for (let i = 1; i < minutes.length; i++) {
        minDiff = Math.min(minDiff, minutes[i] - minutes[i - 1]);
    }
    return minDiff;
};
